package android.widget;import android.content.Context;import android.view.*;public class LinearLayout extends ViewGroup {public static final int VERTICAL=1,HORIZONTAL=0;private int orientation;public LinearLayout(Context c){super(c);}public void setOrientation(int o){orientation=o;}public void setGravity(int g){}public static class LayoutParams {public int width,height;public float weight;public LayoutParams(int w,int h){width=w;height=h;}public LayoutParams(int w,int h,float v){this(w,h);weight=v;}public void setMargins(int l,int t,int r,int b){}}
 @Override public void measure(int w,int h){int height=padding;for(View v:children){v.measure(w,h);height=orientation==VERTICAL?height+v.getMeasuredHeight():Math.max(height,v.getMeasuredHeight()+padding);}setMeasuredDimension(MeasureSpec.getSize(w),height);}
}
